-- Check of the Databricks demo: run each statement, look at the status column.
-- Generated by: node scripts/databricks-demo-check.mjs --write

-- 1. Structure: every table, view and function exists and has its columns.
WITH expected(kind, schema_name, object_name, expected_columns) AS (VALUES
  ('table', 'fin', 'margin_monthly', array('month', 'region_code', 'product_line', 'revenue_eur', 'revenue_plan_eur', 'discount_eur', 'discount_plan_eur', 'cogs_eur', 'cogs_plan_eur', 'fx_cost_eur', 'fx_cost_plan_eur')),
  ('table', 'fin', 'large_discount_deals', array('deal_id', 'month', 'region_code', 'product_line', 'segment', 'customer_id', 'list_value_eur', 'discount_pct', 'policy_limit_pct', 'approval', 'approved_by_role')),
  ('table', 'scm', 'vendors', array('vendor_id', 'vendor_name', 'country', 'otif_90d', 'monthly_capacity_units', 'standard_lead_time_days')),
  ('table', 'scm', 'purchase_orders_seed', array('po_number', 'item', 'material', 'material_description', 'vendor_id', 'plant', 'plant_name', 'buyer_id', 'buyer_name', 'quantity', 'unit_price_eur', 'order_offset_days', 'requested_offset_days', 'confirmed_offset_days', 'inbound_lane', 'lane_congested', 'status')),
  ('table', 'ops', 'jobs', array('job_id', 'job_name', 'owner_team', 'schedule_cron')),
  ('table', 'ops', 'job_runs_seed', array('run_id', 'job_id', 'start_day_offset', 'start_hour', 'start_minute', 'duration_minutes', 'result_state')),
  ('table', 'ops', 'job_task_runs', array('run_id', 'task_key', 'task_order', 'state', 'error_class', 'error_message', 'duration_minutes')),
  ('table', 'ops', 'lineage_edges', array('source_table', 'target_table', 'job_name', 'task_key')),
  ('table', 'ops', 'lineage_closure', array('source_table', 'impacted_table', 'hops')),
  ('table', 'ops', 'downstream_assets', array('asset_name', 'asset_type', 'depends_on_table', 'owner_team', 'criticality', 'refresh_sla_hours', 'note')),
  ('table', 'ops', 'rerun_requests', array('request_id', 'job_run_id', 'requested_by', 'reason', 'proposed_fix', 'status', 'created_at')),
  ('table', 'fin', 'grir_items', array('po_number', 'item', 'vendor_id', 'vendor_name', 'company_code', 'gr_offset_days', 'gr_value_eur', 'invoiced_value_eur', 'description')),
  ('table', 'fin', 'intercompany_items', array('item_id', 'seller_company', 'buyer_company', 'description', 'posting_offset_days', 'seller_amount_eur', 'buyer_amount_eur')),
  ('view', 'fin', 'v_margin_vs_plan', array('month', 'quarter', 'region_code', 'product_line', 'revenue_eur', 'revenue_plan_eur', 'discount_eur', 'discount_plan_eur', 'cogs_eur', 'cogs_plan_eur', 'fx_cost_eur', 'fx_cost_plan_eur', 'net_revenue_eur', 'plan_net_revenue_eur', 'gross_margin_eur', 'plan_gross_margin_eur', 'gross_margin_pct', 'plan_gross_margin_pct', 'margin_delta_pp', 'margin_delta_eur')),
  ('view', 'scm', 'purchase_orders', array('po_number', 'item', 'material', 'material_description', 'vendor_id', 'vendor_name', 'plant', 'plant_name', 'buyer_id', 'buyer_name', 'quantity', 'unit_price_eur', 'net_value_eur', 'order_date', 'requested_delivery_date', 'confirmed_delivery_date', 'days_confirmed_after_requested', 'inbound_lane', 'lane_congested', 'status')),
  ('view', 'ops', 'job_runs', array('run_id', 'job_id', 'job_name', 'owner_team', 'start_time', 'end_time', 'duration_minutes', 'result_state')),
  ('view', 'fin', 'v_grir_open', array('po_number', 'item', 'company_code', 'vendor_id', 'vendor_name', 'description', 'goods_receipt_date', 'age_days', 'gr_value_eur', 'invoiced_value_eur', 'open_value_eur', 'classification')),
  ('view', 'fin', 'v_ic_differences', array('item_id', 'seller_company', 'buyer_company', 'description', 'posting_date', 'seller_amount_eur', 'buyer_amount_eur', 'difference_eur', 'category')),
  ('view', 'scm', 'v_po_delay_scores', array('po_number', 'item', 'buyer_id', 'vendor_id', 'vendor_name', 'material_description', 'quantity', 'net_value_eur', 'requested_delivery_date', 'confirmed_delivery_date', 'delay_probability', 'expected_delay_days', 'top_drivers')),
  ('function', 'scm', 'get_delay_risk_pos', array()),
  ('function', 'scm', 'get_po_detail', array()),
  ('function', 'ops', 'get_failed_runs', array()),
  ('function', 'ops', 'get_run_diagnosis', array()),
  ('function', 'ops', 'get_downstream_impact', array()),
  ('function', 'fin', 'get_grir_accrual_candidates', array()),
  ('function', 'fin', 'get_intercompany_differences', array())
),
found_objects AS (
  SELECT table_schema AS schema_name, table_name AS object_name FROM werkbank_demo.information_schema.tables WHERE table_schema IN ('fin', 'scm', 'ops')
  UNION ALL
  SELECT routine_schema, routine_name FROM werkbank_demo.information_schema.routines WHERE routine_schema IN ('fin', 'scm', 'ops')
),
found_columns AS (
  SELECT table_schema AS schema_name, table_name AS object_name, collect_list(lower(column_name)) AS cols
  FROM werkbank_demo.information_schema.columns WHERE table_schema IN ('fin', 'scm', 'ops') GROUP BY table_schema, table_name
)
SELECT
  e.kind,
  concat(e.schema_name, '.', e.object_name) AS object,
  CASE WHEN o.object_name IS NULL THEN 'PROBLEM: missing'
       WHEN size(array_except(e.expected_columns, coalesce(c.cols, array()))) > 0 THEN 'PROBLEM: columns missing'
       ELSE 'OK' END AS status,
  array_join(array_except(e.expected_columns, coalesce(c.cols, array())), ', ') AS missing_columns
FROM expected e
LEFT JOIN found_objects o ON o.schema_name = e.schema_name AND o.object_name = e.object_name
LEFT JOIN found_columns c ON c.schema_name = e.schema_name AND c.object_name = e.object_name
ORDER BY status DESC, object;

-- 2. Rows: every table holds the rows the load inserts (needs part 1 to be all OK).
SELECT object, expected_rows, actual_rows, CASE WHEN expected_rows = actual_rows THEN 'OK' ELSE 'PROBLEM' END AS status
FROM (
SELECT 'fin.margin_monthly' AS object, 180 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.fin.margin_monthly) AS actual_rows
UNION ALL
SELECT 'fin.large_discount_deals' AS object, 20 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.fin.large_discount_deals) AS actual_rows
UNION ALL
SELECT 'scm.vendors' AS object, 6 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.scm.vendors) AS actual_rows
UNION ALL
SELECT 'scm.purchase_orders_seed' AS object, 26 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.scm.purchase_orders_seed) AS actual_rows
UNION ALL
SELECT 'ops.jobs' AS object, 3 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.jobs) AS actual_rows
UNION ALL
SELECT 'ops.job_runs_seed' AS object, 42 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.job_runs_seed) AS actual_rows
UNION ALL
SELECT 'ops.job_task_runs' AS object, 84 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.job_task_runs) AS actual_rows
UNION ALL
SELECT 'ops.lineage_edges' AS object, 7 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.lineage_edges) AS actual_rows
UNION ALL
SELECT 'ops.lineage_closure' AS object, 24 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.lineage_closure) AS actual_rows
UNION ALL
SELECT 'ops.downstream_assets' AS object, 4 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.ops.downstream_assets) AS actual_rows
UNION ALL
SELECT 'fin.grir_items' AS object, 12 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.fin.grir_items) AS actual_rows
UNION ALL
SELECT 'fin.intercompany_items' AS object, 10 AS expected_rows, (SELECT COUNT(*) FROM werkbank_demo.fin.intercompany_items) AS actual_rows
)
ORDER BY status DESC, object;

-- 3. Story numbers: what the demo says out loud.
SELECT 'GR/IR candidates (function, all companies)' AS check_name, '12' AS expected, CAST((SELECT COUNT(*) FROM werkbank_demo.fin.get_grir_accrual_candidates('ALL')) AS STRING) AS actual
UNION ALL
SELECT 'GR/IR to accrue (8 items, EUR)' AS check_name, '245775.0' AS expected, CAST((SELECT CAST(ROUND(SUM(open_value_eur), 2) AS STRING) FROM werkbank_demo.fin.get_grir_accrual_candidates('ALL') WHERE classification = 'ACCRUE') AS STRING) AS actual
UNION ALL
SELECT 'GR/IR stale for clearing review (EUR)' AS check_name, '17765.0' AS expected, CAST((SELECT CAST(ROUND(SUM(open_value_eur), 2) AS STRING) FROM werkbank_demo.fin.get_grir_accrual_candidates('ALL') WHERE classification = 'STALE_REVIEW') AS STRING) AS actual
UNION ALL
SELECT 'Intercompany differences (view)' AS check_name, '3' AS expected, CAST((SELECT COUNT(*) FROM werkbank_demo.fin.v_ic_differences) AS STRING) AS actual;
